    $andX = [$qb->expr()->in('circle_unique_id', $qb->createNamedParameter($circleIds, \OCP\DB\QueryBuilder\IQueryBuilder::PARAM_STR_ARRAY))];
    if (!$includeTrash) {
        $andX[] = $qb->expr()->isNull('trash_timestamp');
    }
    $qb->select('*')->from($this->tableName)->where($qb->expr()->andX(...$andX));
    try {
        return $this->findEntities($qb);
    } catch (\OCP\DB\Exception $e) {
        throw new \OCA\Collectives\Service\NotFoundException('Failed to run database query', 0, $e);
    }
}

