        if (($position2 = $this->search(array('er', 'en'))) !== false) {
            if ($this->inR1($position2)) {
                $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
            }
        }
        return true;
    }
    // keit
    //      delete if in R2
    //      if preceded by lich or ig, delete if in R2
    if (($position = $this->search(array('keit'))) != false) {
        if ($this->inR2($position)) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        }
        if (($position2 = $this->search(array('lich', 'ig'))) !== false) {
            if ($this->inR2($position2)) {
                $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
            }
        }
        return true;
    }
    return false;
}

