        // if preceded by iv, delete if in R2 (and if further preceded by at, delete if in R2), otherwise,
        if (($position2 = $this->searchIfInR2(array('iv'))) !== false) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
            if (($position3 = $this->searchIfInR2(array('at'))) !== false) {
                $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position3);
