/**
 * @throws NotFoundException
 * @throws NotPermittedException
 * @throws MissingDependencyException
 */
public function getCircle(string $circleId, ?string $userId = null, bool $super = false): \OCA\Circles\Model\Circle
{
    try {
        if ($super) {
            $this->startSuperSession();
        } else {
            $this->startSession($userId);
        }
        /** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
        $circle = $this->circlesManager->getCircle($circleId);
    } catch (\OCA\Circles\Exceptions\CircleNotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    } catch (\OCA\Circles\Exceptions\RequestBuilderException|\OCA\Circles\Exceptions\FederatedItemException $e) {
        throw new \OCA\Collectives\Service\NotPermittedException($e->getMessage(), 0, $e);
    }
    $this->circlesManager->stopSession();
    return $circle;
}

/**
 * @throws NotFoundException
 * @throws NotPermittedException
 * @throws MissingDependencyException
 */
public function getCircles(?string $userId = null): array
{
    try {
        $this->startSession($userId);
        $circleProbe = new \OCA\Circles\Model\Probes\CircleProbe();
        $circleProbe->mustBeMember();
        $dataProbe = new \OCA\Circles\Model\Probes\DataProbe();
        $dataProbe->add(\OCA\Circles\Model\Probes\DataProbe::INITIATOR);
        /** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
        $circles = self::useProbeCircles() ? $this->circlesManager->probeCircles($circleProbe, $dataProbe) : $this->circlesManager->getCircles($circleProbe, true);
    } catch (\OCA\Circles\Exceptions\RequestBuilderException|\OCA\Circles\Exceptions\FederatedItemException $e) {
        throw new \OCA\Collectives\Service\NotPermittedException($e->getMessage(), 0, $e);
    }
    $this->circlesManager->stopSession();
    return $circles;
}

/**
 * @throws NotFoundException
 * @throws NotPermittedException
 */
private function getFederatedUser(?string $userId = null): ?\OCA\Circles\Model\FederatedUser
{
    if ($userId === null) {
        return null;
    }
    try {
        /** @psalm-suppress PossiblyNullReference - we check if circlesManager is null */
        return $this->circlesManager->getFederatedUser($userId, \OCA\Circles\Model\Member::TYPE_USER);
    } catch (\OCA\Circles\Exceptions\CircleNotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    } catch (\OCA\Circles\Exceptions\FederatedItemException|\OCA\Circles\Exceptions\RequestBuilderException $e) {
        throw new \OCA\Collectives\Service\NotPermittedException($e->getMessage(), 0, $e);
    }
}

/**
 * @throws NotFoundException
 * @throws NotPermittedException
 * @throws MissingDependencyException
 */
public function getLevel(string $circleId, string $userId): int
{
    if (is_null($this->circlesManager)) {
        throw new \OCA\Collectives\Service\MissingDependencyException($this->dependencyInjectionError);
    }
    try {
        $this->startSession($userId);
        $circle = $this->circlesManager->getCircle($circleId);
        $member = $circle->getInitiator();
    } catch (\OCA\Circles\Exceptions\CircleNotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    } catch (\OCA\Circles\Exceptions\RequestBuilderException|\OCA\Circles\Exceptions\FederatedItemException $e) {
        throw new \OCA\Collectives\Service\NotPermittedException($e->getMessage(), 0, $e);
    }
    return $member->getLevel();
}

/**
 * @throws NotFoundException
 * @throws NotPermittedException
 * @throws MissingDependencyException
 */
public function hasLevel(string $circleId, string $userId, int $level = \OCA\Circles\Model\Member::LEVEL_MEMBER): bool
{
    return $this->getLevel($circleId, $userId) >= $level;
}

/**
 * @throws MissingDependencyException
 * @throws NotFoundException
 * @throws NotPermittedException
 * @throws RequestBuilderException
 * @throws FederatedItemException
 */
private function startSession(?string $userId = null): void
{
    if (is_null($this->circlesManager)) {
        throw new \OCA\Collectives\Service\MissingDependencyException($this->dependencyInjectionError);
    }
    $federatedUser = $this->getFederatedUser($userId);
    $this->circlesManager->startSession($federatedUser);
}

/**
 * @throws MissingDependencyException
 */
private function startSuperSession(): void
{
    if (is_null($this->circlesManager)) {
        throw new \OCA\Collectives\Service\MissingDependencyException($this->dependencyInjectionError);
    }
    $this->circlesManager->startSuperSession();
}

/**
 * Use `probeCircles()` on
 * - Nextcloud 31+
 * - Nextcloud 30 starting with 30.0.3
 */
private static function useProbeCircles(): bool
{
    [$major, $minor, $micro] = \OCP\Util::getVersion();
    $version = $major . '.' . $minor . '.' . $micro;
    return $major >= 31 || $major === 30 && version_compare($version, '30.0.3', '>=');
}

methods.OCA\\Collectives\\Service\\CollectiveHel:
/**
 * @throws CircleException
 * @throws NotFoundException
 * @throws NotPermittedException
 * @throws MissingDependencyException
 */
public function getCollectivesForUser(string $userId, bool $getLevel = true, bool $getUserSettings = true): array
{
    $circles = $this->circleHelper->getCircles($userId);
    $cids = array_map(static fn($circle) => $circle->getSingleId(), $circles);
    $circles = array_combine($cids, $circles);
    /** @var Collective[] $collectives */
    $collectives = $this->collectiveMapper->findByCircleIds($cids);
    foreach ($collectives as $c) {
        $cid = $c->getCircleId();
        $circle = $circles[$cid];
        $c->setName($circle->getSanitizedName());
        try {
            $c->setLevel($getLevel ? $circle->getInitiator()->getLevel() : 0);
        } catch (\Exception $e) {
            throw new \OCA\Collectives\Service\CircleException($e->getMessage(), 0, $e);
        }
        if ($getUserSettings) {
            // TODO: merge queries for collective and user settings into one?
            $settings = $this->collectiveUserSettingsMapper->findByCollectiveAndUser($c->getId(), $userId);
            $c->setUserPageOrder(($settings ? $settings->getSetting('page_order') : null) ?? \OCA\Collectives\Db\Collective::defaultPageOrder);
            $c->setUserShowMembers(($settings ? $settings->getSetting('show_members') : null) ?? \OCA\Collectives\Db\Collective::defaultShowMembers);
            $c->setUserShowRecentPages(($settings ? $settings->getSetting('show_recent_pages') : null) ?? \OCA\Collectives\Db\Collective::defaultShowRecentPages);
            $c->setUserFavoritePages(($settings ? $settings->getSetting('favorite_pages') : null) ?? []);
        }
    }
    return $collectives;
}

