    $qb = $this->db->getQueryBuilder();
    $qb->select('d.file_id')->selectAlias($qb->func()->sum('d.hit_count'), 'total_hits')->selectAlias($qb->createFunction('MIN(w.term)'), 'matched_term')->from($this->tableName, 'd')->innerJoin('d', 'collectives_s_words', 'w', $qb->expr()->eq('d.word_id', 'w.id'))->where($qb->expr()->eq('d.collective_id', $qb->createNamedParameter($collectiveId, \OCP\DB\QueryBuilder\IQueryBuilder::PARAM_INT)))->andWhere($qb->expr()->in('d.word_id', $qb->createNamedParameter($wordIds, \OCP\DB\QueryBuilder\IQueryBuilder::PARAM_INT_ARRAY)))->groupBy('d.file_id')->orderBy('total_hits', 'DESC')->setMaxResults($limit);
