public static function create(string $code): \Wamania\Snowball\Stemmer\Stemmer
{
    $code = \Joomla\String\StringHelper::strtolower($code);
    foreach (self::LANGS as $classname => $isoCodes) {
        if (in_array($code, $isoCodes)) {
            return new $classname();
        }
