    //  delete if preceded by one of   ta   ssa   sta   lla   lta   na
    if (($position = $this->searchIfInR1(array('an'))) !== false) {
        $word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        $lastThreeLetters = \Joomla\String\StringHelper::substr($word, -3, 3);
        $lastTwoLetters = \Joomla\String\StringHelper::substr($word, -2, 2);
        if (in_array($lastThreeLetters, array('ssa', 'sta', 'lla', 'lta'), true) || in_array($lastTwoLetters, array('na', 'ta'), true)) {
            $this->word = $word;
            $this->r1();
            $this->r2();
            return true;
        }
