    // delete if preceded by one of   tä   ssä   stä   llä   ltä   nä
    if (($position = $this->searchIfInR1(array('än'))) !== false) {
        $word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        $lastThreeLetters = \Joomla\String\StringHelper::substr($word, -3, 3);
        $lastTwoLetters = \Joomla\String\StringHelper::substr($word, -2, 2);
        if (in_array($lastThreeLetters, array('ssä', 'stä', 'llä', 'ltä'), true) || in_array($lastTwoLetters, array('nä', 'tä'), true)) {
            $this->word = $word;
            $this->r1();
