    // delete, and if preceded by LV or ie, delete the last vowel
    if (($position = $this->searchIfInR1(array('n'))) !== false) {
        $lastLetters = \Joomla\String\StringHelper::substr($this->word, $position - 2, 2);
        if (in_array($lastLetters, self::$longVowels, true) || $lastLetters === 'ie') {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position - 1);
        } else {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        }
