    //      delete if preceded by a vowel in RV
    if (($position = $this->search(array('ments', 'ment'))) != false) {
        $before = $position - 1;
        $letter = \Joomla\String\StringHelper::substr($this->word, $before, 1);
        if ($this->inRv($before) && in_array($letter, self::$vowels)) {
