{
    try {
        $collective = $this->findEntity($qb);
        // Return any found collective if $userId is null
        if ($userId === null) {
            return $collective;
        }
        // Return member collectives with at least level `level`
        return $this->circleHelper->hasLevel($collective->getCircleId(), $userId, $level) ? $collective : null;
    } catch (\OCP\AppFramework\Db\DoesNotExistException|\OCP\AppFramework\Db\MultipleObjectsReturnedException) {
        return null;
    } catch (\OCP\DB\Exception $e) {
        throw new \OCA\Collectives\Service\NotFoundException('Failed to run database query.', 0, $e);
