public function get(string $userId): \OCP\Files\Folder
{
    $userHomeFolder = $this->rootFolder->getUserFolder($userId);
    $userCollectivesPath = $this->getUserFolderSetting($userId);
    try {
        /** @var Folder $userCollectivesFolder */
        $userCollectivesFolder = $userHomeFolder->get($userCollectivesPath);
    } catch (\OCP\Files\NotFoundException) {
        \OC_Util::setupFS($userId);
        /** @var Folder $userCollectivesFolder */
        $userCollectivesFolder = $userHomeFolder->get($userCollectivesPath);
    }
    return $userCollectivesFolder;
}

public function getUserFolderSetting(string $userId): string
{
    $defaultUserFolder = $this->appConfig->getValueString('collectives', 'default_user_folder', '');
    // Get collectives user folder from settings and default to translated 'Collectives'
    $userCollectivesPath = $this->config->getUserValue($userId, 'collectives', 'user_folder', $defaultUserFolder);
    if ($userCollectivesPath === '') {
        $user = $this->userManager->get($userId);
        $userLang = $this->l10nFactory->getUserLanguage($user);
        $l10n = $this->l10nFactory->get('collectives', $userLang);
        $userCollectivesPath = DIRECTORY_SEPARATOR . '.' . $l10n->t('Collectives');
        $this->config->setUserValue($userId, 'collectives', 'user_folder', $userCollectivesPath);
    }
    return $userCollectivesPath;
}

methods.OCA\\Collectives\\Model\\PageInfo::fromD:
private function fromData(int $id, string $dirName, bool $isIndexPage, int $parentId, string $fileName, int $timestamp, int $size, ?string $collectivePath = null, ?string $lastUserId = null, ?string $lastUserDisplayName = null, ?string $emoji = null, ?string $subpageOrder = null, ?bool $fullWidth = false, ?string $slug = null, ?string $tags = null, ?array $linkedPageIds = null): void
{
    $this->setId($id);
    if ($isIndexPage) {
        if ($parentId === 0) {
            // Landing page
            $this->setTitle(\OCP\Server::get(\OCP\L10N\IFactory::class)->get('collectives')->t('Landing page'));
        } else {
            // Index page
            $this->setTitle(basename($dirName));
        }
    } else {
        $this->setTitle(basename($fileName, self::SUFFIX));
    }
    $this->setFilePath($dirName);
    $this->setTimestamp($timestamp);
    $this->setSize($size);
    $this->setFileName($fileName);
    if ($collectivePath !== null) {
        $this->setCollectivePath($collectivePath);
    }
    if ($lastUserId !== null) {
        $this->setLastUserId($lastUserId);
    }
    if ($lastUserDisplayName !== null) {
        $this->setLastUserDisplayName($lastUserDisplayName);
    }
    if ($emoji !== null) {
        $this->setEmoji($emoji);
    }
    if ($fullWidth !== null) {
        $this->setFullWidth($fullWidth);
    }
    if ($subpageOrder !== null) {
        $this->setSubpageOrder($subpageOrder);
    }
    if ($slug !== null) {
        $this->setSlug($slug);
    }
    if ($tags !== null) {
        $this->setTags($tags);
    }
    if ($linkedPageIds !== null) {
        $this->setLinkedPageIds($linkedPageIds);
    }
    $this->setParentId($parentId);
}

methods.OCA\\Collectives\\Model\\PageInfo::fromF:
/**
 * @throws InvalidPathException
 * @throws NotFoundException
 */
public function fromFile(\OCP\Files\File $file, int $parentId, ?string $lastUserId = null, ?string $lastUserDisplayName = null, ?string $emoji = null, ?string $subpageOrder = null, ?bool $fullWidth = false, ?string $slug = null, ?string $tags = null, ?array $linkedPageIds = null): void
{
    $dirName = dirname($file->getInternalPath());
    $dirName = $dirName === '.' ? '' : $dirName;
    $isIndexPage = strcmp($file->getName(), self::INDEX_PAGE_TITLE . self::SUFFIX) === 0;
    $mountPoint = explode('/', $file->getMountPoint()->getMountPoint(), 4);
    $collectivePath = count($mountPoint) >= 4 ? rtrim($mountPoint[3], '/') : null;
    $this->fromData($file->getId(), $dirName, $isIndexPage, $parentId, $file->getName(), $file->getMTime(), (int) $file->getSize(), $collectivePath, $lastUserId, $lastUserDisplayName, $emoji, $subpageOrder, $fullWidth, $slug, $tags, $linkedPageIds);
}

