/**
 * @throws NotFoundException
 */
private function getPageByFile(\OCP\Files\File $file, ?\OCP\Files\Node $parent = null): \OCA\Collectives\Model\PageInfo
{
    try {
        $page = $this->pageMapper->findByFileId($file->getId());
    } catch (\OCP\Files\InvalidPathException|\OCP\Files\NotFoundException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    }
    $lastUserId = $page !== null ? $page->getLastUserId() : null;
    $emoji = $page !== null ? $page->getEmoji() : null;
    $subpageOrder = $page !== null ? $page->getSubpageOrder() : null;
    $fullWidth = $page !== null && $page->getFullWidth();
    $slug = $page !== null ? $page->getSlug() : null;
    $tags = $page !== null ? $page->getTags() : null;
    $linkedPageIds = $page !== null ? $this->pageLinkMapper->findByPageId($page->getFileId()) : null;
    $pageInfo = new \OCA\Collectives\Model\PageInfo();
    try {
        $pageInfo->fromFile($file, $this->getParentPageId($file, $parent), $lastUserId, $lastUserId ? $this->userManager->getDisplayName($lastUserId) : null, $emoji, $subpageOrder, $fullWidth, $slug, $tags, $linkedPageIds);
    } catch (\OCP\Files\NotFoundException|\OCP\Files\InvalidPathException $e) {
        throw new \OCA\Collectives\Service\NotFoundException($e->getMessage(), 0, $e);
    }
    return $pageInfo;
}

