    $lastLetter = \Joomla\String\StringHelper::substr($this->r1, -1, 1);
    $secondToLastLetter = \Joomla\String\StringHelper::substr($this->r1, -2, 1);
    if (in_array($secondToLastLetter, self::$consonants, true) && in_array($lastLetter, array('a', 'e', 'i', 'ä'))) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, -1);
        $this->r1();
        $this->r2();
    }
    // c) If R1 ends oj or uj
    // delete the last letter
    $twoLastLetters = \Joomla\String\StringHelper::substr($this->r1, -2, 2);
    if (in_array($twoLastLetters, array('oj', 'uj'))) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, -1);
        $this->r1();
        $this->r2();
    }
    // d) If R1 ends jo
    // delete the last letter
    $twoLastLetters = \Joomla\String\StringHelper::substr($this->r1, -2, 2);
    if ($twoLastLetters === 'jo') {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, -1);
        $this->r1();
        $this->r2();
    }
    // e) If the word ends with a double consonant followed by zero or more
    // vowels, remove the last consonant (so eläkk -> eläk,
    // aatonaatto -> aatonaato)
    $endVowels = '';
    for ($i = \Joomla\String\StringHelper::strlen($this->word) - 1; $i > 0; $i--) {
        $letter = \Joomla\String\StringHelper::substr($this->word, $i, 1);
        if (in_array($letter, self::$vowels, true)) {
            $endVowels = $letter . $endVowels;
        } else {
            // check for double consonant
            $prevLetter = \Joomla\String\StringHelper::substr($this->word, $i - 1, 1);
            if ($prevLetter === $letter) {
                $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $i) . $endVowels;
            }
            break;
        }
    }
}

