/**
 *  In any word, RV is the region after the first vowel, or the end of the word if it contains no vowel.
 */
protected function rv()
{
    $length = \Joomla\String\StringHelper::strlen($this->word);
    $this->rv = '';
    $this->rvIndex = $length;
    for ($i = 0; $i < $length; $i++) {
        $letter = \Joomla\String\StringHelper::substr($this->word, $i, 1);
        if (in_array($letter, self::$vowels)) {
            $this->rv = \Joomla\String\StringHelper::substr($this->word, $i + 1);
            $this->rvIndex = $i + 1;
            return true;
        }
    }
    return false;
}

