 *
 * Search for the longest among the following suffixes
 *      me   se   sela   selo   selas   selos   la   le   lo   las   les   los   nos
 *
 * and delete it, if comes after one of
 *      (a) iéndo   ándo   ár   ér   ír
 *      (b) ando   iendo   ar   er   ir
 *      (c) yendo following u
 *
 *  in RV. In the case of (c), yendo must lie in RV, but the preceding u can be outside it.
 *  In the case of (a), deletion is followed by removing the acute accent (for example, haciéndola -> haciendo).
 */
private function step0()
{
    if (($position = $this->searchIfInRv(array('selas', 'selos', 'las', 'los', 'les', 'nos', 'selo', 'sela', 'me', 'se', 'la', 'le', 'lo'))) != false) {
        $suffixe = \Joomla\String\StringHelper::substr($this->word, $position);
        // a
        $a = array('iéndo', 'ándo', 'ár', 'ér', 'ír');
        $a = array_map(function ($item) use ($suffixe) {
            return $item . $suffixe;
        }, $a);
        if (($position2 = $this->searchIfInRv($a)) !== false) {
            $suffixe2 = \Joomla\String\StringHelper::substr($this->word, $position2);
            $suffixe2 = \Wamania\Snowball\Transliterate::utf8_latin_to_ascii($suffixe2);
            // unaccent
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
            $this->word .= $suffixe2;
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
            return true;
        }
        // b
        $b = array('iendo', 'ando', 'ar', 'er', 'ir');
        $b = array_map(function ($item) use ($suffixe) {
            return $item . $suffixe;
        }, $b);
        if (($position2 = $this->searchIfInRv($b)) !== false) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
            return true;
        }
        // c
        if (($position2 = $this->searchIfInRv(array('yendo' . $suffixe))) != false) {
            $before = \Joomla\String\StringHelper::substr($this->word, $position2 - 1, 1);
            if (isset($before) && $before == 'u') {
                $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
                return true;
            }
        }
    }
    return false;
}

/**
 * Step 1
 */
private function step1()
{
    // anza   anzas   ico   ica   icos   icas   ismo   ismos   able   ables   ible   ibles   ista
    // istas   oso   osa   osos   osas   amiento   amientos   imiento   imientos
    //      delete if in R2
    if (($position = $this->search(array('imientos', 'imiento', 'amientos', 'amiento', 'osas', 'osos', 'osa', 'oso', 'istas', 'ista', 'ibles', 'ible', 'ables', 'able', 'ismos', 'ismo', 'icas', 'icos', 'ica', 'ico', 'anzas', 'anza'))) != false) {
        if ($this->inR2($position)) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        }
        return true;
    }
    // adora   ador   ación   adoras   adores   aciones   ante   antes   ancia   ancias
    //      delete if in R2
    //      if preceded by ic, delete if in R2
    if (($position = $this->search(array('adoras', 'adora', 'aciones', 'ación', 'adores', 'ador', 'antes', 'ante', 'ancias', 'ancia'))) != false) {
        if ($this->inR2($position)) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        }
        if ($position2 = $this->searchIfInR2(array('ic'))) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
        }
        return true;
    }
    // logía   logías
    //      replace with log if in R2
    if (($position = $this->search(array('logías', 'logía'))) != false) {
        if ($this->inR2($position)) {
            $this->word = preg_replace('#(logías|logía)$#u', 'log', $this->word);
        }
        return true;
    }
    // ución   uciones
    //      replace with u if in R2
    if (($position = $this->search(array('uciones', 'ución'))) != false) {
        if ($this->inR2($position)) {
            $this->word = preg_replace('#(uciones|ución)$#u', 'u', $this->word);
        }
        return true;
    }
    // encia   encias
    //      replace with ente if in R2
    if (($position = $this->search(array('encias', 'encia'))) != false) {
        if ($this->inR2($position)) {
            $this->word = preg_replace('#(encias|encia)$#u', 'ente', $this->word);
        }
        return true;
    }
    // amente
    //      delete if in R1
    //      if preceded by iv, delete if in R2 (and if further preceded by at, delete if in R2), otherwise,
    //      if preceded by os, ic or ad, delete if in R2
    if (($position = $this->search(array('amente'))) != false) {
        // delete if in R1
        if ($this->inR1($position)) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        }
        // if preceded by iv, delete if in R2 (and if further preceded by at, delete if in R2), otherwise,
        if (($position2 = $this->searchIfInR2(array('iv'))) !== false) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
            if (($position3 = $this->searchIfInR2(array('at'))) !== false) {
                $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position3);
            }
            // if preceded by os, ic or ad, delete if in R2
        } elseif (($position4 = $this->searchIfInR2(array('os', 'ic', 'ad'))) != false) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position4);
        }
        return true;
    }
    // mente
    //      delete if in R2
    //      if preceded by ante, able or ible, delete if in R2
    if (($position = $this->search(array('mente'))) != false) {
        // delete if in R2
        if ($this->inR2($position)) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        }
        // if preceded by ante, able or ible, delete if in R2
        if (($position2 = $this->searchIfInR2(array('ante', 'able', 'ible'))) != false) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
        }
        return true;
    }
    // idad   idades
    //      delete if in R2
    //      if preceded by abil, ic or iv, delete if in R2
    if (($position = $this->search(array('idades', 'idad'))) != false) {
        // delete if in R2
        if ($this->inR2($position)) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        }
        // if preceded by abil, ic or iv, delete if in R2
        if (($position2 = $this->searchIfInR2(array('abil', 'ic', 'iv'))) != false) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
        }
        return true;
    }
    // iva   ivo   ivas   ivos
    //      delete if in R2
    //      if preceded by at, delete if in R2
    if (($position = $this->search(array('ivas', 'ivos', 'iva', 'ivo'))) != false) {
        // delete if in R2
        if ($this->inR2($position)) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        }
        // if preceded by at, delete if in R2
        if (($position2 = $this->searchIfInR2(array('at'))) != false) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
        }
        return true;
    }
    return false;
}

/**
 * Step 2a: Verb suffixes beginning y
 */
private function step2a()
{
    // if found, delete if preceded by u
    // (Note that the preceding u need not be in RV.)
    if (($position = $this->searchIfInRv(array('yamos', 'yendo', 'yeron', 'yan', 'yen', 'yais', 'yas', 'yes', 'yo', 'yó', 'ya', 'ye'))) != false) {
        $before = \Joomla\String\StringHelper::substr($this->word, $position - 1, 1);
        if (isset($before) && $before == 'u') {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
            return true;
        }
    }
    return false;
}

/**
 * Step 2b: Other verb suffixes
 *      Search for the longest among the following suffixes in RV, and perform the action indicated.
 */
private function step2b()
{
    //      delete
    if (($position = $this->searchIfInRv(array('iésemos', 'iéramos', 'ábamos', 'iríamos', 'eríamos', 'aríamos', 'áramos', 'ásemos', 'eríais', 'aremos', 'eremos', 'iremos', 'asteis', 'ieseis', 'ierais', 'isteis', 'aríais', 'irían', 'aréis', 'erían', 'erías', 'eréis', 'iréis', 'irías', 'ieran', 'iesen', 'ieron', 'iendo', 'ieras', 'iríais', 'arían', 'arías', 'amos', 'imos', 'ados', 'idos', 'irán', 'irás', 'erán', 'erás', 'ería', 'iría', 'íais', 'arán', 'arás', 'aría', 'iera', 'iese', 'aste', 'iste', 'aban', 'aran', 'asen', 'aron', 'ando', 'abas', 'adas', 'idas', 'ases', 'aras', 'aré', 'erá', 'eré', 'áis', 'ías', 'irá', 'iré', 'aba', 'ían', 'ada', 'ara', 'ase', 'ida', 'ado', 'ido', 'ará', 'ad', 'ed', 'id', 'ís', 'ió', 'ar', 'er', 'ir', 'as', 'ía', 'an'))) != false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        return true;
    }
    // en   es   éis   emos
    //      delete, and if preceded by gu delete the u (the gu need not be in RV)
    if (($position = $this->searchIfInRv(array('éis', 'emos', 'en', 'es'))) != false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        if (($position2 = $this->search(array('gu'))) != false) {
            $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2 + 1);
        }
        return true;
    }
}

/**
 * Step 3: residual suffix
 * Search for the longest among the following suffixes in RV, and perform the action indicated.
 */
private function step3()
{
    // os   a   o   á   í   ó
    //      delete if in RV
    if (($position = $this->searchIfInRv(array('os', 'a', 'o', 'á', 'í', 'ó'))) != false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        return true;
    }
    // e   é
    //      delete if in RV, and if preceded by gu with the u in RV delete the u
    if (($position = $this->searchIfInRv(array('e', 'é'))) != false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        if (($position2 = $this->searchIfInRv(array('u'))) != false) {
            $before = \Joomla\String\StringHelper::substr($this->word, $position2 - 1, 1);
            if (isset($before) && $before == 'g') {
                $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position2);
                return true;
            }
        }
    }
    return false;
}

methods.Wamania\\Snowball\\Stemmer\\Stem::r1:
/**
 * R1 is the region after the first non-vowel following a vowel, or the end of the word if there is no such non-vowel.
 */
protected function r1()
{
    list($this->r1Index, $this->r1) = $this->rx($this->word);
}

methods.Wamania\\Snowball\\Stemmer\\Stem::r2:
/**
 * R2 is the region after the first non-vowel following a vowel in R1, or the end of the word if there is no such non-vowel.
 */
protected function r2()
{
    list($index, $value) = $this->rx($this->r1);
    $this->r2 = $value;
    $this->r2Index = $this->r1Index + $index;
}

methods.Wamania\\Snowball\\Stemmer\\Stem::rv:
/**
 * Used by spanish, italian, portuguese, etc (but not by french)
 *
 * If the second letter is a consonant, RV is the region after the next following vowel,
 * or if the first two letters are vowels, RV is the region after the next consonant,
 * and otherwise (consonant-vowel case) RV is the region after the third letter.
 * But RV is the end of the word if these positions cannot be found.
 */
protected function rv()
{
    $length = \Joomla\String\StringHelper::strlen($this->word);
    $this->rv = '';
    $this->rvIndex = $length;
    if ($length < 3) {
        return true;
    }
    $first = \Joomla\String\StringHelper::substr($this->word, 0, 1);
    $second = \Joomla\String\StringHelper::substr($this->word, 1, 1);
    // If the second letter is a consonant, RV is the region after the next following vowel,
    if (!in_array($second, static::$vowels)) {
        for ($i = 2; $i < $length; $i++) {
            $letter = \Joomla\String\StringHelper::substr($this->word, $i, 1);
            if (in_array($letter, static::$vowels)) {
                $this->rvIndex = $i + 1;
                $this->rv = \Joomla\String\StringHelper::substr($this->word, $i + 1);
                return true;
            }
        }
    }
    // or if the first two letters are vowels, RV is the region after the next consonant,
    if (in_array($first, static::$vowels) && in_array($second, static::$vowels)) {
        for ($i = 2; $i < $length; $i++) {
            $letter = \Joomla\String\StringHelper::substr($this->word, $i, 1);
            if (!in_array($letter, static::$vowels)) {
                $this->rvIndex = $i + 1;
                $this->rv = \Joomla\String\StringHelper::substr($this->word, $i + 1);
                return true;
            }
        }
    }
    // and otherwise (consonant-vowel case) RV is the region after the third letter.
    if (!in_array($first, static::$vowels) && in_array($second, static::$vowels)) {
        $this->rv = \Joomla\String\StringHelper::substr($this->word, 3);
        $this->rvIndex = 3;
        return true;
    }
}

methods.Wamania\\Snowball\\Stemmer\\Stem::rx:
/**
 * Common function for R1 and R2
 * Search the region after the first non-vowel following a vowel in $word, or the end of the word if there is no such non-vowel.
 * R1 : $in = $this->word
 * R2 : $in = R1
 */
protected function rx($in)
{
    $length = \Joomla\String\StringHelper::strlen($in);
    // defaults
    $value = '';
    $index = $length;
    // we search all vowels
    $vowels = array();
    for ($i = 0; $i < $length; $i++) {
        $letter = \Joomla\String\StringHelper::substr($in, $i, 1);
        if (in_array($letter, static::$vowels)) {
            $vowels[] = $i;
        }
    }
    // search the non-vowel following a vowel
    foreach ($vowels as $position) {
        $after = $position + 1;
        $letter = \Joomla\String\StringHelper::substr($in, $after, 1);
        if (!in_array($letter, static::$vowels)) {
            $index = $after + 1;
            $value = \Joomla\String\StringHelper::substr($in, $after + 1);
            break;
        }
    }
    return array($index, $value);
}

methods.Wamania\\Snowball\\Stemmer\\Stem::search:
protected function search($suffixes, $offset = 0)
{
    $length = \Joomla\String\StringHelper::strlen($this->word);
    if ($offset > $length) {
        return false;
    }
    foreach ($suffixes as $suffixe) {
        if (($position = \Joomla\String\StringHelper::strrpos($this->word, $suffixe, $offset)) !== false && \Joomla\String\StringHelper::strlen($suffixe) + $position == $length) {
            return $position;
        }
    }
    return false;
}

methods.Wamania\\Snowball\\Stemmer\\Swedish::has:
/**
 * Define a valid s-ending as one of
 * b   c   d   f   g   h   j   k   l   m   n   o   p   r   t   v   y
 *
 * @param string $ending
 * @return boolean
 */
private function hasValidSEnding($word)
{
    $lastLetter = \Joomla\String\StringHelper::substr($word, -1, 1);
    return in_array($lastLetter, array('b', 'c', 'd', 'f', 'g', 'h', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'r', 't', 'v', 'y'));
}

methods.Wamania\\Snowball\\Stemmer\\Swedish::ste:
/**
 * {@inheritdoc}
 */
public function stem($word)
{
    $this->word = \Joomla\String\StringHelper::strtolower($word);
    // R2 is not used: R1 is defined in the same way as in the German stemmer
    $this->r1();
    // then R1 is adjusted so that the region before it contains at least 3 letters.
    if ($this->r1Index < 3) {
        $this->r1Index = 3;
        $this->r1 = \Joomla\String\StringHelper::substr($this->word, 3);
    }
    // Do each of steps 1, 2 3 and 4.
    $this->step1();
    $this->step2();
    $this->step3();
    return $this->word;
}

/**
 * Step 1
 * Search for the longest among the following suffixes in R1, and perform the action indicated.
 */
private function step1()
{
    // a   arna   erna   heterna   orna   ad   e   ade   ande   arne   are   aste   en   anden   aren   heten
    // ern   ar   er   heter   or   as   arnas   ernas   ornas   es   ades   andes   ens   arens   hetens
    // erns   at   andet   het   ast
    //      delete
    if (($position = $this->searchIfInR1(array('heterna', 'hetens', 'ornas', 'andes', 'arnas', 'heter', 'ernas', 'anden', 'heten', 'andet', 'arens', 'orna', 'arna', 'erna', 'aren', 'ande', 'ades', 'arne', 'erns', 'aste', 'ade', 'ern', 'het', 'ast', 'are', 'ens', 'or', 'es', 'ad', 'en', 'at', 'ar', 'as', 'er', 'a', 'e'))) !== false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        return true;
    }
    //  s
    //      delete if preceded by a valid s-ending
    if (($position = $this->searchIfInR1(array('s'))) !== false) {
        $word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        if ($this->hasValidSEnding($word)) {
            $this->word = $word;
        }
    }
}

/**
 * Step 2
 * Search for one of the following suffixes in R1, and if found delete the last letter.
 */
private function step2()
{
    // dd   gd   nn   dt   gt   kt   tt
    if ($this->searchIfInR1(array('dd', 'gd', 'nn', 'dt', 'gt', 'kt', 'tt')) !== false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, -1);
    }
}

/**
 * Step 3:
 * Search for the longest among the following suffixes in R1, and perform the action indicated.
 */
private function step3()
{
    // lig   ig   els
    //      delete
    if (($position = $this->searchIfInR1(array('lig', 'ig', 'els'))) !== false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, $position);
        return true;
    }
    // löst
    //      replace with lös
    if ($this->searchIfInR1(array('löst')) !== false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, -1);
        return true;
    }
    // fullt
    //      replace with full
    if ($this->searchIfInR1(array('fullt')) !== false) {
        $this->word = \Joomla\String\StringHelper::substr($this->word, 0, -1);
        return true;
    }
}

methods.function utf8_from_unicode@joomla/phputf:
//--------------------------------------------------------------------
/**
* Takes an array of ints representing the Unicode characters and returns
* a UTF-8 string. Astral planes are supported ie. the ints in the
* input can be > 0xFFFF. Occurrances of the BOM are ignored. Surrogates
* are not allowed.
* Returns false if the input array contains ints that represent
* surrogates or are outside the Unicode range
* and raises a PHP error at level E_USER_WARNING
* Note: this function has been modified slightly in this library to use
* output buffering to concatenate the UTF-8 string (faster) as well as
* reference the array by it's keys
* @param array of unicode code points representing a string
* @return mixed UTF-8 string or FALSE if array contains invalid code points
* @author <hsivonen@iki.fi>
* @see utf8_to_unicode
* @see http://hsivonen.iki.fi/php-utf8/
* @package utf8
*/
function utf8_from_unicode($arr)
{
    \ob_start();
    foreach (\array_keys($arr) as $k) {
        # ASCII range (including control chars)
        if ($arr[$k] >= 0 && $arr[$k] <= 0x7f) {
            echo \chr($arr[$k]);
            # 2 byte sequence
        } elseif ($arr[$k] <= 0x7ff) {
            echo \chr(0xc0 | $arr[$k] >> 6);
            echo \chr(0x80 | $arr[$k] & 0x3f);
            # Byte order mark (skip)
        } elseif ($arr[$k] == 0xfeff) {
            // nop -- zap the BOM
            # Test for illegal surrogates
        } elseif ($arr[$k] >= 0xd800 && $arr[$k] <= 0xdfff) {
            // found a surrogate
            \trigger_error('utf8_from_unicode: Illegal surrogate ' . 'at index: ' . $k . ', value: ' . $arr[$k], \E_USER_WARNING);
            return \false;
            # 3 byte sequence
        } elseif ($arr[$k] <= 0xffff) {
            echo \chr(0xe0 | $arr[$k] >> 12);
            echo \chr(0x80 | $arr[$k] >> 6 & 0x3f);
            echo \chr(0x80 | $arr[$k] & 0x3f);
            # 4 byte sequence
        } elseif ($arr[$k] <= 0x10ffff) {
            echo \chr(0xf0 | $arr[$k] >> 18);
            echo \chr(0x80 | $arr[$k] >> 12 & 0x3f);
            echo \chr(0x80 | $arr[$k] >> 6 & 0x3f);
            echo \chr(0x80 | $arr[$k] & 0x3f);
        } else {
            \trigger_error('utf8_from_unicode: Codepoint out of Unicode range ' . 'at index: ' . $k . ', value: ' . $arr[$k], \E_USER_WARNING);
            // out of range
            return \false;
        }
    }
    $result = \ob_get_contents();
    \ob_end_clean();
    return $result;
}

methods.function utf8_strlen@joomla/phputf8/mbst:
//--------------------------------------------------------------------
/**
* Wrapper round mb_strlen
* Assumes you have mb_internal_encoding to UTF-8 already
* Note: this function does not count bad bytes in the string - these
* are simply ignored
* @param string UTF-8 string
* @return int number of UTF-8 characters in string
* @package utf8
*/
function utf8_strlen($str)
{
    return \mb_strlen($str);
}

methods.function utf8_strpos@joomla/phputf8/mbst:
//--------------------------------------------------------------------
/**
* Assumes mbstring internal encoding is set to UTF-8
* Wrapper around mb_strpos
* Find position of first occurrence of a string
* @param string haystack
* @param string needle (you should validate this with utf8_is_valid)
* @param integer offset in characters (from left)
* @return mixed integer position or FALSE on failure
* @package utf8
*/
function utf8_strpos($str, $search, $offset = \false)
{
    if ($offset === \false) {
        return \mb_strpos($str, $search);
    } else {
        return \mb_strpos($str, $search, $offset);
    }
}

methods.function utf8_strpos@joomla/phputf8/nati:
//--------------------------------------------------------------------
/**
* UTF-8 aware alternative to strpos
* Find position of first occurrence of a string
* Note: This will get alot slower if offset is used
* Note: requires utf8_strlen amd utf8_substr to be loaded
* @param string haystack
* @param string needle (you should validate this with utf8_is_valid)
* @param integer offset in characters (from left)
* @return mixed integer position or FALSE on failure
* @see http://www.php.net/strpos
* @see utf8_strlen
* @see utf8_substr
* @package utf8
*/
function utf8_strpos($str, $needle, $offset = \null)
{
    if (\is_null($offset)) {
        $ar = \explode($needle, $str, 2);
        if (\count($ar) > 1) {
            return \utf8_strlen($ar[0]);
        }
        return \false;
    } else {
        if (!\is_int($offset)) {
